// only where whitespace or the end of the text follows. Requiring that keeps
// decimals ("3.14"), domains ("example.com") and "a.b.c" in one piece.
const TERMINATOR_PATTERN = /([.!?]+)(["'”’)\]]*)(?=\s|$)/g;

